INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5010745, 730435, 4010, '<td valign="top">Excellent entry.  Contrast on the black and white is good.  I think the featureless sky real accentuates the boringness of suburbia.  Well done</td>', 'Excellent entry.  Contrast on the black and white is good.  I think the featureless sky real accentuates the boringness of suburbia.  Well done', '2008-10-15 22:02:01.000000', NULL, 1),
