(5010764, 730510, 73942, '<td valign="top">nice leading lines</td>', 'nice leading lines', '2008-10-15 22:15:46.000000', NULL, 1),
(5010808, 730437, 66041, '<td valign="top">Like the though, but there''s too much contrast for me between the shocking white sign and the darkened background...</td>', 'Like the though, but there''s too much contrast for me between the shocking white sign and the darkened background...', '2008-10-15 23:02:11.000000', NULL, 1),
