(5010870, 730435, 16046, '<td valign="top">Awesome</td>', 'Awesome', '2008-10-16 00:05:18.000000', NULL, 1),
(5010875, 729104, 66041, '<td valign="top">cool.   Love the sepia/B&amp;W treatment here.   Does wonders to increase the mood.  (althoguh that don''t walk sign is red, isn''t it..  ;-)    I really feel like I"m out there in the rain.</td>', 'cool.   Love the sepia/B&W treatment here.   Does wonders to increase the mood.  (althoguh that don''t walk sign is red, isn''t it..  ;-)    I really feel like I"m out there in the rain.', '2008-10-16 00:12:14.000000', NULL, 1),
