(5010877, 730349, 16046, '<td valign="top">Great idea</td>', 'Great idea', '2008-10-16 00:14:06.000000', NULL, 1),
(5010878, 730394, 16046, '<td valign="top">Should ribbon, IMO, well done</td>', 'Should ribbon, IMO, well done', '2008-10-16 00:16:05.000000', NULL, 1),
(5010884, 730528, 66041, '<td valign="top">I like the photo (and the house  ;-)   but I might have gone with Landscape to get those two trees in there and a little less grass...</td>', 'I like the photo (and the house  ;-)   but I might have gone with Landscape to get those two trees in there and a little less grass...', '2008-10-16 00:22:11.000000', NULL, 1),
(5010888, 730566, 66041, '<td valign="top">hmmm.  Looks more like a city than it does suburbia</td>', 'hmmm.  Looks more like a city than it does suburbia', '2008-10-16 00:23:02.000000', NULL, 1),
(5010893, 730392, 66041, '<td valign="top">I like that you included a lot of sky in this.  The clouds lend a nice pattern to the overall photo...</td>', 'I like that you included a lot of sky in this.  The clouds lend a nice pattern to the overall photo...', '2008-10-16 00:25:10.000000', NULL, 1),
(5010896, 730500, 66041, '<td valign="top">The houses are getting lost in here...   I would have cut a lot of sky out and some of the street to get more of a panoramic shot, to at least make the houses the primary focus...</td>', 'The houses are getting lost in here...   I would have cut a lot of sky out and some of the street to get more of a panoramic shot, to at least make the houses the primary focus...', '2008-10-16 00:27:00.000000', NULL, 1),
(5010900, 730555, 66041, '<td valign="top">The angle and effects add quirkiness and interest to what could have been an ordinary shot...</td>', 'The angle and effects add quirkiness and interest to what could have been an ordinary shot...', '2008-10-16 00:29:26.000000', NULL, 1),
(5011085, 730557, 69325, '<td valign="top">i like the capture of the water...even if it does look like you are peeing :)<br/>/6</td>', 'i like the capture of the water...even if it does look like you are peeing :)/6', '2008-10-16 06:24:36.000000', NULL, 1),
