(5011091, 730146, 69325, '<td valign="top">nice eye on this one, really like the mood and feel you have captured /8</td>', 'nice eye on this one, really like the mood and feel you have captured /8', '2008-10-16 06:28:01.000000', NULL, 1),
(5011092, 730393, 6999, '<td valign="top">I rather like this one, for this challenge. The pull between the leading line of the path and the middle-ground and background subjects lends it a strong dynamic. The saturated green of the grass, the un-fenced path, the hyper-neatness of everything, all speak strongly of the expected un-natural tidiness of the suburbs; ''we can control everything, even to the riot of nature''. Makes you wonder what sinisterness goes on behind those facades.</td>', 'I rather like this one, for this challenge. The pull between the leading line of the path and the middle-ground and background subjects lends it a strong dynamic. The saturated green of the grass, the un-fenced path, the hyper-neatness of everything, all speak strongly of the expected un-natural tidiness of the suburbs; ''we can control everything, even to the riot of nature''. Makes you wonder what sinisterness goes on behind those facades.', '2008-10-16 06:28:41.000000', NULL, 1),
(5011093, 730444, 69325, '<td valign="top">looks like it could be from my own neighborhood, not much of interest in this shot unfortunately /5</td>', 'looks like it could be from my own neighborhood, not much of interest in this shot unfortunately /5', '2008-10-16 06:28:42.000000', NULL, 1),
(5011094, 728891, 6999, '<td valign="top">Perhaps it''s just from the edging into frame of that landing, but there''s a good sense of a further world about this shot. Something we might, in our suburban fantasy, happily ignore whilst we feed the ducks?</td>', 'Perhaps it''s just from the edging into frame of that landing, but there''s a good sense of a further world about this shot. Something we might, in our suburban fantasy, happily ignore whilst we feed the ducks?', '2008-10-16 06:30:03.000000', NULL, 1),
(5011095, 730088, 69325, '<td valign="top">must have been fun to get this shot /5</td>', 'must have been fun to get this shot /5', '2008-10-16 06:31:19.000000', NULL, 1),
(5011096, 730562, 69325, '<td valign="top">would like to see a longer angle on the fence, and the b&amp;w conversion seems a tad dark, at least on my monitor /5</td>', 'would like to see a longer angle on the fence, and the b&w conversion seems a tad dark, at least on my monitor /5', '2008-10-16 06:32:09.000000', NULL, 1),
