(5013692, 730510, 62187, '<td valign="top">Wow...thank goodness I bought my house when I did. You have an excellent photo for the challenge and technically perfect: as far as I can see. 10</td>', 'Wow...thank goodness I bought my house when I did. You have an excellent photo for the challenge and technically perfect: as far as I can see. 10', '2008-10-18 16:19:15.000000', NULL, 1),
(5013693, 730497, 62187, '<td valign="top">The edit gives an ordinary snapshot an excellent photographic quality. Nice work: 10</td>', 'The edit gives an ordinary snapshot an excellent photographic quality. Nice work: 10', '2008-10-18 16:20:00.000000', NULL, 1),
