(5013885, 730349, 60173, '<td valign="top">Did you borrow a sign from someone actually sitting at that intersection? There''s some damn expensive cars in the lot at that shopping center sometimes. Some cars you would think would be sitting in a locked garage and never driven because they''re in the 90k+ range.<br/> <br/>As for the actual photo, it looks too processed to me.</td>', 'Did you borrow a sign from someone actually sitting at that intersection? There''s some damn expensive cars in the lot at that shopping center sometimes. Some cars you would think would be sitting in a locked garage and never driven because they''re in the 90k+ range. As for the actual photo, it looks too processed to me.', '2008-10-18 20:14:41.000000', NULL, 1),
(5013916, 730556, 95101, '<td valign="top">Wow nows theres your cookie cutter houses ..hehe. Like the angle of all the rooftops.</td>', 'Wow nows theres your cookie cutter houses ..hehe. Like the angle of all the rooftops.', '2008-10-18 20:57:42.000000', NULL, 1),
(5014041, 730553, 5521, '<td valign="top">I like it, but it doesn''t say suburbia to me at all.</td>', 'I like it, but it doesn''t say suburbia to me at all.', '2008-10-19 00:24:25.000000', NULL, 1),
(5014054, 730349, 74059, '<td valign="top">Ha!!  Awesome.</td>', 'Ha!!  Awesome.', '2008-10-19 00:48:49.000000', NULL, 1),
(5014057, 730511, 74059, '<td valign="top">Really cool idea but there''s so much going on that it loses impact. My eye doesn''t know where to look.</td>', 'Really cool idea but there''s so much going on that it loses impact. My eye doesn''t know where to look.', '2008-10-19 00:50:32.000000', NULL, 1),
(5014058, 730510, 74059, '<td valign="top">Being a city girl this is EXACTLY what I think of when I think of the suburbs. So mundane it''s maddening. Great capture.</td>', 'Being a city girl this is EXACTLY what I think of when I think of the suburbs. So mundane it''s maddening. Great capture.', '2008-10-19 00:51:58.000000', NULL, 1);
