(5015619, 730304, 30982, '<td valign="top">The roof right next door, right outside the window, tends to lend to that suburbia feel.... Nice work on the shelves - awesome place to have a desk/work area.</td>', 'The roof right next door, right outside the window, tends to lend to that suburbia feel.... Nice work on the shelves - awesome place to have a desk/work area.', '2008-10-20 08:33:41.000000', NULL, 0),
(5015621, 730533, 30982, '<td valign="top">What a great sport he is!  Very funny, very good.  And he''s rather a good looking, umm, well... he''s rather good looking, even in that get-up!</td>', 'What a great sport he is!  Very funny, very good.  And he''s rather a good looking, umm, well... he''s rather good looking, even in that get-up!', '2008-10-20 08:35:33.000000', NULL, 0),
(5015636, 730533, 52549, '<td valign="top">Great shot and a great expression on his face. This had me in stitches and he''s one very brave guy (or he''s terrified of his wife ;-)) Either way, great work, Judi!</td>', 'Great shot and a great expression on his face. This had me in stitches and he''s one very brave guy (or he''s terrified of his wife ;-)) Either way, great work, Judi!', '2008-10-20 08:52:07.000000', NULL, 0),
